with metrics as (select *, ntile(3) over w_hist as discount_pct_bucket, lead(discount_pct, 1) over w_ordered as next_discount_pct, min(discount_pct) over w_ordered_2 as promo_code_min_discount_pct from promotions window w_hist as (partition by channel order by discount_pct asc, id asc), w_ordered as (partition by channel order by starts_on asc, id asc), w_ordered_2 as (partition by promo_code, channel)) select id, promo_code, starts_on, next_discount_pct from metrics order by next_discount_pct desc;
